ate childProcess: ChildProcess\n  ) {\n    childProcess.onOutput((output) => {\n      this.terminalOutputChunks.push(output);\n      this.outputCallbacks.forEach((cb) => cb(output));\n    });\n\n    childProcess.onExit((message) => {\n      this.isAlive = false;\n\n      const code = messageToCode(message);\n      childProcess.cleanup();\n\n      const terminalOutput = this.terminalOutputChunks.join('');\n      this.terminalOutputChunks = [];\n      this.exitCallbacks.forEach((cb) => cb(code, terminalOutput));\n    });\n  }\n\n  async getResults(): Promise<{ code: number; terminalOutput: string }> {\n    return new Promise((res) => {\n      this.onExit((code, terminalOutput) => {\n        res({ code, terminalOutput });\n      });\n    });\n  }\n\n  onExit(callback: (code: number, terminalOutput: string) => void): void {\n    this.exitCallbacks.push(callback);\n  }\n\n  onOutput(callback: (message: string) => void): void {\n    this.outputCallbacks.push(callback);\n  }\n\n  getPid(): number | undefined {\n    return this.childProcess.getPid();\n  }\n\n  kill(s?: NodeJS.Signals): void {\n    if (this.isAlive) {\n      try {\n        this.childProcess.kill(s || 'SIGTERM');\n      } catch {\n        // when the child process completes before we explicitly call kill, this will throw\n        // do nothing\n      } finally {\n        this.isAlive = false;\n      }\n    }\n  }\n\n  getParserAndWriter() {\n    return this.childProcess.getParserAndWriter();\n  }\n}\n\nexport class PseudoTtyProcessWithSend extends PseudoTtyProcess {\n  constructor(\n    public rustPseudoTerminal: RustPseudoTerminal,\n    _childProcess: ChildProcess,\n    private id: string,\n    private pseudoIpc: PseudoIPCServer\n  ) {\n    super(rustPseudoTerminal, _childProcess);\n  }\n\n  send(message: Serializable) {\n    this.pseudoIpc.sendMessageToChild(this.id, message);\n  }\n}\n\nfunction supportedPtyPlatform() {\n  if (IS_WASM) {\n    return false;\n  }\n  if (process.platform !== 'win32') {\n    return true;\n  }\n\n  // TODO: Re-enable Windows support when it's stable\n  // Currently, there's an issue with control chars.\n  // See: https://github.com/nrwl/nx/issues/22358\n  if (process.env.NX_WINDOWS_PTY_SUPPORT !== 'true') {\n    return false;\n  }\n\n  let windowsVersion = os.release().split('.');\n  let windowsBuild = windowsVersion[2];\n\n  if (!windowsBuild) {\n    return false;\n  }\n\n  // Mininum supported Windows version:\n  // https://en.wikipedia.org/wiki/Windows_10,_version_1809\n  // https://learn.microsoft.com/en-us/windows/console/createpseudoconsole#requirements\n  if (+windowsBuild < 17763) {\n    return false;\n  } else {\n    return true;\n  }\n}\n"],"names":["PseudoTerminal","PseudoTtyProcess","PseudoTtyProcessWithSend","createPseudoTerminal","pseudoTerminalShutdownCallbacks","process","on","code","forEach","cb","skipSupportCheck","isSupported","Error","pseudoTerminal","RustPseudoTerminal","push","shutdown","bind","id","stdout","isTTY","supportedPtyPlatform","rustPseudoTerminal","pseudoIPCPath","getForkedProcessOsSocketPath","pid","toString","pseudoIPC","PseudoIPCServer","initialized","childProcesses","Set","init","cp","kill","codeToSignal","close","runCommand","command","cwd","execArgv","jsEnv","quiet","tty","add","fork","script","commandLabel","waitForChildReady","sendMessageToChildren","message","onMessageFromChildren","callback","childProcess","isAlive","exitCallbacks","outputCallbacks","terminalOutputChunks","onOutput","output","onExit","messageToCode","cleanup","terminalOutput","join","getResults","Promise","res","getPid","s","getParserAndWriter","_childProcess","pseudoIpc","send","sendMessageToChild","IS_WASM","platform","env","NX_WINDOWS_PTY_SUPPORT","windowsVersion","os","release","split","windowsBuild"],"mappings":";;;;4DACoB;6BACyB;wBACa;2BAC1B;2BAEY;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;+BAoB/BA;;;eAAAA;;;QAAAA;;;;+BAqHAC;;;eAAAA;;;QAAAA;;;;+BAoEAC;;;eAAAA;;;QAAAA;;;;+BArMGC;;;eAAAA;;;QAAAA;;;;AANhB,oEAAoE;AACpE,MAAMC,kCAA