 => flag !== 'nxReleaseVersionData'\n    );\n    if (filteredOverrides.length > 0) {\n      bodyLines.push('');\n      bodyLines.push(`${output.dim('With additional flags:')}`);\n      filteredOverrides\n        .map(([flag, value]) => formatFlags('', flag, value))\n        .forEach((arg) => bodyLines.push(arg));\n    }\n\n    const title = `Running ${formatTargetsAndProjects(\n      this.projectNames,\n      this.args.targets,\n      this.tasks\n    )}:`;\n\n    output.log({\n      color: 'cyan',\n      title,\n      bodyLines,\n    });\n\n    output.addVerticalSeparatorWithoutNewLines('cyan');\n  }\n\n  endCommand(): void {\n    output.addNewline();\n\n    if (this.tasks.length === 0) {\n      output.logSingleLine(`No tasks were run`);\n      return;\n    }\n    if (this.failedTasks.length === 0) {\n      output.addVerticalSeparatorWithoutNewLines('green');\n\n      const bodyLines =\n        this.cachedTasks.length > 0\n          ? [\n              output.dim(\n                `Nx read the output from the cache instead of running the command for ${this.cachedTasks.length} out of ${this.tasks.length} tasks.`\n              ),\n            ]\n          : [];\n\n      output.success({\n        title: `Successfully ran ${formatTargetsAndProjects(\n          this.projectNames,\n          this.args.targets,\n          this.tasks\n        )}`,\n        bodyLines,\n      });\n    } else {\n      output.addVerticalSeparatorWithoutNewLines('red');\n\n      const bodyLines = [];\n      const skippedTasks = this.skippedTasks();\n      if (skippedTasks.length > 0) {\n        bodyLines.push(\n          output.dim(\n            'Tasks not run because their dependencies failed or --nx-bail=true:'\n          ),\n          '',\n          ...skippedTasks.map((task) => `${output.dim('-')} ${task.id}`),\n          ''\n        );\n      }\n      bodyLines.push(\n        output.dim('Failed tasks:'),\n        '',\n        ...[...this.failedTasks.values()].map(\n          (task) => `${output.dim('-')} ${task.id}`\n        )\n      );\n      output.error({\n        title: `Running ${formatTargetsAndProjects(\n          this.projectNames,\n          this.args.targets,\n          this.tasks\n        )} failed`,\n        bodyLines,\n      });\n    }\n  }\n\n  private skippedTasks() {\n    return this.tasks.filter((t) => !this.allCompletedTasks.has(t.id));\n  }\n\n  endTasks(taskResults: TaskResult[]): void {\n    for (let t of taskResults) {\n      this.allCompletedTasks.set(t.task.id, t.task);\n      if (t.status === 'failure') {\n        this.failedTasks.push(t.task);\n      } else if (t.status === 'local-cache') {\n        this.cachedTasks.push(t.task);\n      } else if (t.status === 'local-cache-kept-existing') {\n        this.cachedTasks.push(t.task);\n      } else if (t.status === 'remote-cache') {\n        this.cachedTasks.push(t.task);\n      }\n    }\n  }\n\n  printTaskTerminalOutput(\n    task: Task,\n    cacheStatus: TaskStatus,\n    terminalOutput: string\n  ) {\n    const args = getPrintableCommandArgsForTask(task);\n    output.logCommandOutput(args.join(' '), cacheStatus, terminalOutput);\n  }\n}\n"],"names":["StaticRunManyTerminalOutputLifeCycle","projectNames","tasks","args","taskOverrides","failedTasks","cachedTasks","allCompletedTasks","Map","startCommand","length","output","logSingleLine","formatTargetsAndProjects","targets","bodyLines","map","affectedProject","dim","filteredOverrides","Object","entries","filter","flag","push","value","formatFlags","forEach","arg","title","log","color","addVerticalSeparatorWithoutNewLines","endCommand","addNewline","success","skippedTasks","task","id","values","error","t","has","endTasks","taskResults","set","status","printTaskTerminalOutput","cacheStatus","terminalOutput","getPrintableCommandArgsForTask","logCommandOutput","join"],"mappings":";;;;wBAAuB;uBAEwB;iCAGO;+BAUzCA;;;eAAAA;;;QAAAA;;;;AAAN,MAAMA;IAKX,YACE,AAAiBC,YAAsB,EACvC,AAAiBC,KAAa,EAC9B,AAAiBC,IAGhB,EACD,AAAiBC,aAAkB,CACnC;aAPiBH,eAAAA;