+{"version":3,"sources":["/workspace/repo/packages/nx/src/utils/logger.ts"],"sourcesContent":["import * as pc from 'picocolors';\nimport { isOnDaemon } from '../daemon/is-on-daemon';\nimport { serverLogger } from '../daemon/logger';\n\nexport const NX_PREFIX = pc.inverse(pc.bold(pc.cyan(' NX ')));\n\nexport const NX_ERROR = pc.inverse(pc.bold(pc.red(' ERROR ')));\n\ntype LogDriver = Pick<Console, 'warn' | 'error' | 'info' | 'log' | 'debug'>;\n\nexport function createLogger(driver: LogDriver) {\n  return {\n    warn: (...v) => driver.warn(...v.map((s) => pc.bold(pc.yellow(s)))),\n    error: (s) => {\n      if (typeof s === 'string' && s.startsWith('NX ')) {\n        driver.error(`\\n${NX_ERROR} ${pc.bold(pc.red(s.slice(3)))}\\n`);\n      } else if (s instanceof Error && s.stack) {\n        driver.error(pc.bold(pc.red(s.stack)));\n      } else {\n        driver.error(pc.bold(pc.red(s)));\n      }\n    },\n    info: (s) => {\n      if (typeof s === 'string' && s.startsWith('NX ')) {\n        driver.info(`\\n${NX_PREFIX} ${pc.bold(s.slice(3))}\\n`);\n      } else {\n        driver.info(s);\n      }\n    },\n    log: (...s) => {\n      driver.log(...s);\n    },\n    debug: (...s) => {\n      driver.debug(...s);\n    },\n    fatal: (...s) => {\n      driver.error(...s);\n    },\n    verbose: (...s) => {\n      if (process.env.NX_VERBOSE_LOGGING === 'true') {\n        // verbose logs go to stderr to prevent things like `nx show projects | grep`\n        // breaking when you enable verbose logging. The only potential breakage from\n        // this would be if a tool counts any output on stderr as being an issue, but\n        // there are likely other places that would trigger those same issues.\n        driver.warn(...s);\n      }\n    },\n  };\n}\n\nexport const logger = createLogger(\n  isOnDaemon()\n    ? (() => {\n        const log = serverLogger.log.bind(serverLogger);\n        return {\n          warn: log,\n          error: log,\n          debug: log,\n          info: log,\n          log: log,\n        };\n      })()\n    : console\n);\n\nexport function stripIndent(str: string): string {\n  const match = str.match(/^[ \\t]*(?=\\S)/gm);\n  if (!match) {\n    return str;\n  }\n  const indent = match.reduce((r, a) => Math.min(r, a.length), Infinity);\n  const regex = new RegExp(`^[ \\\\t]{${indent}}`, 'gm');\n  return str.replace(regex, '');\n}\n"],"names":["NX_ERROR","NX_PREFIX","createLogger","logger","stripIndent","pc","inverse","bold","cyan","red","driver","warn","v","map","s","yellow","error","startsWith","slice","Error","stack","info","log","debug","fatal","verbose","process","env","NX_VERBOSE_LOGGING","isOnDaemon","serverLogger","bind","console","str","match","indent","reduce","r","a","Math","min","length","Infinity","regex","RegExp","replace"],"mappings":";;;;oEAAoB;4BACO;wBACE;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;+BAIhBA;;;eAAAA;;;QAAAA;;;;+BAFAC;;;eAAAA;;;QAAAA;;;;+BAMGC;;;eAAAA;;;QAAAA;;;;+BAwCHC;;;eAAAA;;;QAAAA;;;;+BAeGC;;;eAAAA;;;QAAAA;;;;AA7DT,MAAMH,YAAYI,YAAGC,OAAO,CAACD,YAAGE,IAAI,CAACF,YAAGG,IAAI,CAAC;AAE7C,MAAMR,WAAWK,YAAGC,OAAO,CAACD,YAAGE,IAAI,CAACF,YAAGI,GAAG,CAAC;AAI3C,SAASP,aAAaQ,MAAiB;IAC5C,OAAO;QACLC,MAAM,CAAC,GAAGC,IAAMF,OAAOC,IAAI,IAAIC,EAAEC,GAAG,CAAC,CAACC,IAAMT,YAAGE,IAAI,CAACF,YAAGU,MAAM,CAACD;QAC9DE,OAAO,CAACF;YACN,IAAI,OAAOA,MAAM,YAAYA,EAAEG,UAAU,CAAC,QAAQ;gBAChDP,OAAOM,KAAK,CAAC,CAAC,EAAE,UAAEhB,SAAS,CAAC,EAAEK,YAAGE,IAAI,CAACF,YAAGI,GAAG,CAACK,EAAEI,KAAK,CAAC,KAAK,EAAE,CAAC;YAC/D,OAAO,IAAIJ,aAAaK,SAASL,EAAEM,KAAK,EAAE;gBACxCV,OAAOM,KAAK,CAACX,YAAGE,IAAI,CAACF,YAAGI,GAAG,CAACK,EAAEM,KAAK;YACrC,OAAO;gBACLV,OAAOM,KAAK,CAACX,YAAGE,IAAI,CAACF,YAAGI,GAAG,CAACK;YAC9B;QACF;QACAO,MAAM,CAACP;YACL,IAAI,OAAOA,MAAM,YAAYA,EAAEG,UAAU,CAAC,QAAQ;gBAChDP,OAAOW,IAAI,CAAC,CAAC,EAAE,UAAEpB,UAAU,CAAC,EAAEI,YAAGE,IAAI,CAACO,EAAEI,KAAK,CAAC,IAAI,EAAE,CAAC;YACvD,OAAO;gBACLR,OAAOW,IAAI,CAACP;YACd;QACF;QACAQ,KAAK,CAAC,GAAGR;YACPJ,OAAOY,GAAG,IAAIR;QAChB;QACAS,OAAO,CAAC,GAAGT;YACTJ,OAAOa,KAAK,IAAIT;QAClB;QACAU,OAAO,CAAC